-- sunshine-workflow-manager（workflow-manager :8230 · 库 sunshine_workflow · 全量 v1）
USE sunshine_workflow;

CREATE TABLE workflow_definition (
    tenant_id       VARCHAR(64) NOT NULL DEFAULT 'default',
    id              VARCHAR(64) NOT NULL,
    display_name    VARCHAR(128) NOT NULL,
    description     VARCHAR(512),
    mode            VARCHAR(24) NOT NULL DEFAULT 'workflow',
    enabled         TINYINT(1) NOT NULL DEFAULT 0,
    active_version  INT NOT NULL DEFAULT 0,
    source          VARCHAR(16) NOT NULL DEFAULT 'studio',
    kind            VARCHAR(16) NOT NULL DEFAULT 'all' COMMENT '会话形态：chat|task|all（与 conversation.kind 同轴）',
    maintainer      VARCHAR(64),
    created_at      TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at      TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    PRIMARY KEY (tenant_id, id)
);

CREATE TABLE workflow_version (
    id              BIGINT AUTO_INCREMENT PRIMARY KEY,
    tenant_id       VARCHAR(64) NOT NULL,
    workflow_id     VARCHAR(64) NOT NULL,
    version         INT NOT NULL,
    status          VARCHAR(16) NOT NULL DEFAULT 'draft',
    plan_json       MEDIUMTEXT NOT NULL,
    catalog_meta    JSON,
    published_at    TIMESTAMP NULL,
    created_at      TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    UNIQUE KEY uk_workflow_version (tenant_id, workflow_id, version),
    CONSTRAINT fk_workflow_version_def FOREIGN KEY (tenant_id, workflow_id)
        REFERENCES workflow_definition (tenant_id, id)
);

-- 标杆 workflow 种子（published v1，plan_json 含 layout；source=seed；节点 id = {type}-{8位hex}；由 scripts/sync_enterprise_workflows.py --write-sql 生成）

-- finance-list
INSERT INTO workflow_definition (tenant_id, id, display_name, description, mode, enabled, active_version, source, kind) VALUES ('default', 'finance-list', '我的报销查询', '列出当前用户报销单（可按 status），不做合规分析', 'workflow', 1, 1, 'seed', 'chat');
INSERT INTO workflow_version (tenant_id, workflow_id, version, status, plan_json, catalog_meta, published_at) VALUES ('default', 'finance-list', 1, 'published', '{"planId":null,"reason":"导入自 sunshine-workflows.yaml · finance-list","nodes":[{"id":"start","type":"start","displayName":"开始","params":{}},{"id":"tool-f7a3b2c1","type":"tool","displayName":"查询我的报销单","params":{"tool":"sdk__sunshine-biz__list_my_expenses","retry.maxAttempts":"2","retry.backoffMs":"500","retry.onFailure":"continue"},"inputs":[{"name":"status","source":"{{plan.params.status}}","type":"string","required":false}]},{"id":"answer","type":"answer","displayName":"回答","params":{"prompt":"根据财务工具查询结果回答用户问题。\\n\\n约束：\\n- 仅依据下方「数据」作答；数据中未出现的制度条文、审批标准、金额门槛等一律禁止撰写或猜测。\\n- 本流程只查询我的报销单：即使用户提到「循环 / 检索制度 / 合规分析」，也只列示数据中的单据；可用一句话说明「当前流程仅列出我的报销」。\\n- 禁止向用户暴露英文流程/工具内部名。\\n- 若「数据」中非空（有条目、条数>0、含 id/金额/标题等），必须逐条列出，不得回答「没有数据」。\\n- 仅当数据明确为空数组或条数为 0 时，才可说明当前无报销记录。\\n- 不要编造单据；不要省略工具返回的字段。\\n- 输出用简洁 Markdown 列表或表格列单据即可，勿写长篇合规/制度报告。\\n\\n数据：\\n{{tool-f7a3b2c1.output}}","retry.maxAttempts":"2","retry.backoffMs":"500","retry.onFailure":"fail_fast"}}],"edges":[{"from":"start","to":"tool-f7a3b2c1"},{"from":"tool-f7a3b2c1","to":"answer"}],"layout":{"start":{"x":48,"y":72},"tool-f7a3b2c1":{"x":268,"y":72},"answer":{"x":488,"y":72}}}', '{"examples":["我有哪些待报销","列出我的报销单"],"nodeSummary":["start","tool","answer"]}', CURRENT_TIMESTAMP);

