INSERT INTO workflow_definition (tenant_id, id, display_name, description, mode, enabled, active_version, source, kind) VALUES ('default', 'finance-smart', '报销智能分析', '对照费用制度只读分析当前用户报销是否合规（含 Agent；不可提交报销）', 'workflow', 1, 1, 'seed', 'chat');
INSERT INTO workflow_version (tenant_id, workflow_id, version, status, plan_json, catalog_meta, published_at) VALUES ('default', 'finance-smart', 1, 'published', '{"planId":null,"reason":"企业化只读报销分析：rag→list→agent(finance-analysis，无 submit)","nodes":[{"id":"start","type":"start","displayName":"开始","params":{}},{"id":"rag-fsmart1","type":"rag","displayName":"费用制度检索","params":{"query":"费用差旅网约车报销：{{start.userQuery}}","topK":"3","retry.maxAttempts":"1","retry.backoffMs":"500","retry.onFailure":"continue"}},{"id":"tool-d4e8f901","type":"tool","displayName":"查询我的报销单","params":{"tool":"sdk__sunshine-biz__list_my_expenses","retry.maxAttempts":"2","retry.backoffMs":"500","retry.onFailure":"continue"},"inputs":[{"name":"status","source":"{{plan.params.status}}","type":"string","required":false}]},{"id":"agent-b2c6d803","type":"agent","displayName":"智能体分析","params":{"query":"{{start.userQuery}}","context":"制度检索：{{rag-fsmart1.output}}\\n报销列表：{{tool-d4e8f901.output}}","skill":"finance-analysis","tools":"sdk__sunshine-biz__list_my_expenses,sdk__sunshine-biz__get_expense_detail","maxIters":"4","systemOverlay":"本节点仅输出内部只读分析结论，不面向用户；禁止调用白名单外工具；禁止提交报销；禁止虚构金额。","retry.maxAttempts":"1","retry.backoffMs":"500","retry.onFailure":"continue"}},{"id":"answer","type":"answer","displayName":"回答","params":{"prompt":"根据 Agent 分析结果生成用户可见回答。\\n\\n约束：禁止向用户暴露英文流程/工具内部名；仅依据下方分析作答。\\n\\n分析：\\n{{agent-b2c6d803.answer}}","retry.maxAttempts":"2","retry.backoffMs":"500","retry.onFailure":"fail_fast"}}],"edges":[{"from":"start","to":"rag-fsmart1"},{"from":"rag-fsmart1","to":"tool-d4e8f901"},{"from":"tool-d4e8f901","to":"agent-b2c6d803"},{"from":"agent-b2c6d803","to":"answer"}],"layout":{"start":{"x":48,"y":72},"rag-fsmart1":{"x":248,"y":72},"tool-d4e8f901":{"x":448,"y":72},"agent-b2c6d803":{"x":648,"y":72},"answer":{"x":868,"y":72}}}', '{"examples":["对照制度看我的报销是否合规","分析我的报销与费用制度"],"nodeSummary":["start","rag","tool","agent","answer"]}', CURRENT_TIMESTAMP);

