INSERT INTO workflow_version (tenant_id, workflow_id, version, status, plan_json, catalog_meta, published_at) VALUES ('default', 'knowledge-dual', 1, 'published', '{"planId":null,"reason":"4.7.2 并行双 RAG 标杆（BPMN parallel-gateway）","nodes":[{"id":"start","type":"start","displayName":"开始","params":{}},{"id":"pg-a1b2c3d4","type":"parallel-gateway","displayName":"并行分叉","params":{"retry.maxAttempts":"1","retry.backoffMs":"500","retry.onFailure":"continue"}},{"id":"rag-a1b2c3d4","type":"rag","displayName":"人事制度检索","params":{"query":"人事制度：{{start.userQuery}}","topK":"3","retry.maxAttempts":"1","retry.backoffMs":"500","retry.onFailure":"continue"}},{"id":"rag-e5f6a7b8","type":"rag","displayName":"费用制度检索","params":{"query":"费用制度：{{start.userQuery}}","topK":"3","retry.maxAttempts":"1","retry.backoffMs":"500","retry.onFailure":"continue"}},{"id":"join-c9d0e1f2","type":"join","displayName":"并行汇总","params":{"retry.maxAttempts":"2","retry.backoffMs":"500","retry.onFailure":"continue"}},{"id":"answer","type":"answer","displayName":"回答","params":{"prompt":"你是企业知识助手。综合下方「人事制度检索」与「费用制度检索」结果回答，不得编造。\\n\\n若两路均为空，回复：企业知识库中暂无相关规定。\\n禁止暴露英文流程/工具内部名。\\n\\n人事制度检索：\\n{{rag-a1b2c3d4.output}}\\n\\n费用制度检索：\\n{{rag-e5f6a7b8.output}}","retry.maxAttempts":"2","retry.backoffMs":"500","retry.onFailure":"fail_fast"}}],"edges":[{"from":"start","to":"pg-a1b2c3d4"},{"from":"pg-a1b2c3d4","to":"rag-a1b2c3d4"},{"from":"pg-a1b2c3d4","to":"rag-e5f6a7b8"},{"from":"rag-a1b2c3d4","to":"join-c9d0e1f2"},{"from":"rag-e5f6a7b8","to":"join-c9d0e1f2"},{"from":"join-c9d0e1f2","to":"answer"}],"layout":{"start":{"x":48,"y":72},"pg-a1b2c3d4":{"x":322,"y":80},"rag-a1b2c3d4":{"x":488,"y":28},"rag-e5f6a7b8":{"x":488,"y":116},"join-c9d0e1f2":{"x":762,"y":80},"answer":{"x":928,"y":72}}}', '{"examples":["青松假和网约车报销上限一起查","青松假有多少天、怎么申请"],"nodeSummary":["start","parallel-gateway","rag","join","answer"]}', CURRENT_TIMESTAMP);

