INSERT INTO workflow_version (tenant_id, workflow_id, version, status, plan_json, catalog_meta, published_at) VALUES ('default', 'knowledge-branch', 1, 'published', '{"planId":null,"reason":"4.13.7 exclusive-gateway OR 多条件边条件标杆（报销 OR 发票）","nodes":[{"id":"start","type":"start","displayName":"开始","params":{}},{"id":"xg-b1c2d3e4","type":"exclusive-gateway","displayName":"条件分支","params":{"retry.maxAttempts":"1","retry.backoffMs":"500","retry.onFailure":"continue"}},{"id":"rag-f1a2b3c4","type":"rag","displayName":"财务制度检索","params":{"query":"{{start.userQuery}}","topK":"3","retry.maxAttempts":"1","retry.backoffMs":"500","retry.onFailure":"continue"}},{"id":"rag-d5e6f7a8","type":"rag","displayName":"人事制度检索","params":{"query":"{{start.userQuery}}","topK":"3","retry.maxAttempts":"1","retry.backoffMs":"500","retry.onFailure":"continue"}},{"id":"answer","type":"answer","displayName":"回答","params":{"prompt":"你是企业制度助手。根据下方检索结果回答，不得编造。\\n\\n若检索为空，回复：企业知识库中暂无相关规定。\\n禁止暴露 knowledge-branch 等内部名称。\\n\\n财务制度检索：\\n{{rag-f1a2b3c4.output}}\\n\\n人事制度检索：\\n{{rag-d5e6f7a8.output}}","retry.maxAttempts":"2","retry.backoffMs":"500","retry.onFailure":"fail_fast"}}],"edges":[{"from":"start","to":"xg-b1c2d3e4"},{"from":"xg-b1c2d3e4","to":"rag-f1a2b3c4","condition":{"logic":"or","items":[{"left":"{{start.userQuery}}","op":"contains","right":"报销"},{"left":"{{start.userQuery}}","op":"contains","right":"发票"}]}},{"from":"xg-b1c2d3e4","to":"rag-d5e6f7a8","default":true},{"from":"rag-f1a2b3c4","to":"answer"},{"from":"rag-d5e6f7a8","to":"answer"}],"layout":{"start":{"x":48,"y":72},"xg-b1c2d3e4":{"x":280,"y":80},"rag-f1a2b3c4":{"x":480,"y":28},"rag-d5e6f7a8":{"x":480,"y":116},"answer":{"x":720,"y":72}}}', '{"examples":["网约车报销需要哪些材料","青松假怎么申请"],"nodeSummary":["start","exclusive-gateway","rag","answer"],"intentAfter":"将按条件分支知识检索流程处理"}', CURRENT_TIMESTAMP);

