INSERT INTO workflow_version (tenant_id, workflow_id, version, status, plan_json, catalog_meta, published_at) VALUES ('default', 'knowledge-loop', 1, 'published', '{"planId":null,"reason":"4.13.7 loop 容器标杆（do-while 多条件 AND：检索含「继续」且待报销未「已完成」则再轮；框内 rag→list→leave→agent）","nodes":[{"id":"start","type":"start","displayName":"开始","params":{}},{"id":"loop-a1b2c3d4","type":"loop","displayName":"条件循环","params":{"conditions":[{"left":"{{rag-l1o2o3p4.output}}","op":"contains","right":"继续"},{"left":"{{tool-t1o2o3p4.output}}","op":"not_contains","right":"已完成"}],"conditionLogic":"and","maxIterations":"2","onMaxIterations":"exit","retry.maxAttempts":"1","retry.backoffMs":"500","retry.onFailure":"fail_fast"}},{"id":"rag-l1o2o3p4","type":"rag","parentId":"loop-a1b2c3d4","displayName":"知识检索","params":{"query":"{{start.userQuery}}","topK":"3","retry.maxAttempts":"1","retry.backoffMs":"500","retry.onFailure":"continue"}},{"id":"tool-t1o2o3p4","type":"tool","parentId":"loop-a1b2c3d4","displayName":"查询我的待报销","params":{"tool":"sdk__sunshine-biz__list_my_expenses","retry.maxAttempts":"2","retry.backoffMs":"500","retry.onFailure":"continue"},"inputs":[{"name":"status","source":"{{plan.params.status}}","type":"string","required":false}]},{"id":"tool-leave01","type":"tool","parentId":"loop-a1b2c3d4","displayName":"查询假期余额","params":{"tool":"sdk__sunshine-biz__get_leave_balance","retry.maxAttempts":"2","retry.backoffMs":"500","retry.onFailure":"continue"}},{"id":"agent-a1g2e3n4","type":"agent","parentId":"loop-a1b2c3d4","displayName":"综合分析","params":{"query":"{{start.userQuery}}","context":"检索：{{rag-l1o2o3p4.output}}\\n待报销：{{tool-t1o2o3p4.output}}\\n假期余额：{{tool-leave01.output}}","skill":"finance-analysis","tools":"sdk__sunshine-biz__list_my_expenses","maxIters":"3","systemOverlay":"本节点仅输出内部分析结论；综合制度检索、待报销与假期余额，禁止编造。","retry.maxAttempts":"1","retry.backoffMs":"500","retry.onFailure":"continue"}},{"id":"answer","type":"answer","displayName":"回答","params":{"prompt":"你是企业助手。根据下方循环分析结论回答，不得编造。\\n\\n若结论为空，回复：暂无可用结果。\\n禁止暴露 knowledge-loop 等内部名称。\\n\\n循环分析：\\n{{loop-a1b2c3d4.output}}","retry.maxAttempts":"2","retry.backoffMs":"500","retry.onFailure":"fail_fast"}}],"edges":[{"from":"start","to":"loop-a1b2c3d4"},{"from":"rag-l1o2o3p4","to":"tool-t1o2o3p4"},{"from":"tool-t1o2o3p4","to":"tool-leave01"},{"from":"tool-leave01","to":"agent-a1g2e3n4"},{"from":"loop-a1b2c3d4","to":"answer"}],"layout":{"start":{"x":48,"y":72},"loop-a1b2c3d4":{"x":200,"y":40,"width":780,"height":160},"rag-l1o2o3p4":{"x":224,"y":92},"tool-t1o2o3p4":{"x":400,"y":92},"tool-leave01":{"x":576,"y":92},"agent-a1g2e3n4":{"x":752,"y":92},"answer":{"x":1040,"y":72}}}', '{"examples":["分析青松假余额和我的待报销","继续分析青松假余额和我的待报销"],"nodeSummary":["start","loop","rag","tool","agent","answer"],"intentAfter":"将按条件循环（检索→工具→智能体）流程处理"}', CURRENT_TIMESTAMP);

-- sandbox-agent
INSERT INTO workflow_definition (tenant_id, id, display_name, description, mode, enabled, active_version, source, kind) VALUES ('default', 'sandbox-agent', '工作区沙箱写文件', 'Workflow agent 节点默认沙箱：用沙箱工具在对话工作区写文件后汇总（4.5 SUB 默认沙箱标杆）', 'workflow', 1, 1, 'seed', 'chat');
INSERT INTO workflow_version (tenant_id, workflow_id, version, status, plan_json, catalog_meta, published_at) VALUES ('default', 'sandbox-agent', 1, 'published', '{"planId":null,"reason":"4.5 SUB 默认沙箱标杆（start→agent→answer；复用对话级 /workspace）","nodes":[{"id":"start","type":"start","displayName":"开始","params":{}},{"id":"agent-s4b0x7a1","type":"agent","displayName":"沙箱写文件","params":{"query":"{{start.userQuery}}","context":"请在对话沙箱 /workspace 完成用户请求的文件写入；沙箱六工具已注入，无需 Catalog 白名单。","maxIters":"4","systemOverlay":"本节点为 Workflow 子 Agent，仅输出内部结论供下游润色。\\n必须使用 sandbox__write（新建）或 sandbox__edit（已存在）在 /workspace 落盘；过渡语后立刻 tool call。\\n禁止编造「已写入」而未实际调用工具；完成后用简短中文说明路径与要点。","retry.maxAttempts":"1","retry.backoffMs":"500","retry.onFailure":"continue"}},{"id":"answer","type":"answer","displayName":"回答","params":{"prompt":"根据子 Agent 结论生成用户可见回答。\\n\\n约束：禁止暴露 sandbox-agent、sandbox__* 等内部名；用中文说明已写入的工作区文件路径与内容要点。\\n\\n子 Agent 结论：\\n{{agent-s4b0x7a1.answer}}","retry.maxAttempts":"2","retry.backoffMs":"500","retry.onFailure":"fail_fast"}}],"edges":[{"from":"start","to":"agent-s4b0x7a1"},{"from":"agent-s4b0x7a1","to":"answer"}],"layout":{"start":{"x":48,"y":72},"agent-s4b0x7a1":{"x":268,"y":72},"answer":{"x":488,"y":72}}}', '{"examples":["在工作区写一份 hello.txt 内容为 hello sandbox","用沙箱新建 /workspace/note.md"],"nodeSummary":["start","agent","answer"],"intentAfter":"将按工作区沙箱写文件流程处理"}', CURRENT_TIMESTAMP);

-- hr-leave-assist
INSERT INTO workflow_definition (tenant_id, id, display_name, description, mode, enabled, active_version, source, kind) VALUES ('default', 'hr-leave-assist', '假期助手', '检索假期制度并查询余额/请假单；用户明确申请时可 submit（HITL）', 'workflow', 1, 1, 'seed', 'chat');
INSERT INTO workflow_version (tenant_id, workflow_id, version, status, plan_json, catalog_meta, published_at) VALUES ('default', 'hr-leave-assist', 1, 'published', '{"planId":null,"reason":"企业假期助手：rag→余额→请假列表→agent(可 submit_leave)","nodes":[{"id":"start","type":"start","displayName":"开始","params":{}},{"id":"rag-hrleave1","type":"rag","displayName":"假期制度检索","params":{"query":"{{start.userQuery}}","topK":"3","retry.maxAttempts":"1","retry.backoffMs":"500","retry.onFailure":"continue"}},{"id":"tool-hrbal01","type":"tool","displayName":"查询假期余额","params":{"tool":"sdk__sunshine-biz__get_leave_balance","retry.maxAttempts":"2","retry.backoffMs":"500","retry.onFailure":"continue"}},{"id":"tool-hrlist01","type":"tool","displayName":"查询请假单","params":{"tool":"sdk__sunshine-biz__list_leave_requests","retry.maxAttempts":"2","retry.backoffMs":"500","retry.onFailure":"continue"}},{"id":"agent-hrleave1","type":"agent","displayName":"假期助手","params":{"query":"{{start.userQuery}}","context":"制度：{{rag-hrleave1.output}}\\n余额：{{tool-hrbal01.output}}\\n请假单：{{tool-hrlist01.output}}","skill":"policy-review","tools":"sdk__sunshine-biz__submit_leave_request","maxIters":"4","systemOverlay":"仅当用户明确申请且假别/日期等参数齐全时调用提交请假；否则只输出只读结论；禁止编造余额或单据。","retry.maxAttempts":"1","retry.backoffMs":"500","retry.onFailure":"continue"}},{"id":"answer","type":"answer","displayName":"回答","params":{"prompt":"根据上游检索、工具与 Agent 结论回答用户。\\n\\n约束：禁止向用户暴露英文流程/工具内部名；仅依据下方数据与结论作答，禁止编造。\\n\\n制度：\\n{{rag-hrleave1.output}}\\n\\n余额：\\n{{tool-hrbal01.output}}\\n\\n请假单：\\n{{tool-hrlist01.output}}\\n\\nAgent 结论：\\n{{agent-hrleave1.answer}}","retry.maxAttempts":"2","retry.backoffMs":"500","retry.onFailure":"fail_fast"}}],"edges":[{"from":"start","to":"rag-hrleave1"},{"from":"rag-hrleave1","to":"tool-hrbal01"},{"from":"tool-hrbal01","to":"tool-hrlist01"},{"from":"tool-hrlist01","to":"agent-hrleave1"},{"from":"agent-hrleave1","to":"answer"}],"layout":{"start":{"x":48,"y":72},"rag-hrleave1":{"x":248,"y":72},"tool-hrbal01":{"x":448,"y":72},"tool-hrlist01":{"x":648,"y":72},"agent-hrleave1":{"x":848,"y":72},"answer":{"x":1068,"y":72}}}', '{"examples":["青松假还有几天，我的请假单呢","帮我申请明天一天青松假"],"nodeSummary":["start","rag","tool","agent","answer"],"intentAfter":"将按假期助手流程处理"}', CURRENT_TIMESTAMP);

-- expense-compliance
INSERT INTO workflow_definition (tenant_id, id, display_name, description, mode, enabled, active_version, source, kind) VALUES ('default', 'expense-compliance', '费用合规闭环', '检索费用制度并列出我的报销；合规分析，明确提交时可 submit_expense（HITL）', 'workflow', 1, 1, 'seed', 'chat');
INSERT INTO workflow_version (tenant_id, workflow_id, version, status, plan_json, catalog_meta, published_at) VALUES ('default', 'expense-compliance', 1, 'published', '{"planId":null,"reason":"费用合规闭环：rag→list→agent(可 submit_expense)","nodes":[{"id":"start","type":"start","displayName":"开始","params":{}},{"id":"rag-expcomp1","type":"rag","displayName":"费用制度检索","params":{"query":"{{start.userQuery}}","topK":"3","retry.maxAttempts":"1","retry.backoffMs":"500","retry.onFailure":"continue"}},{"id":"tool-explist1","type":"tool","displayName":"查询我的报销单","params":{"tool":"sdk__sunshine-biz__list_my_expenses","retry.maxAttempts":"2","retry.backoffMs":"500","retry.onFailure":"continue"},"inputs":[{"name":"status","source":"{{plan.params.status}}","type":"string","required":false}]},{"id":"agent-expcomp1","type":"agent","displayName":"合规分析","params":{"query":"{{start.userQuery}}","context":"制度：{{rag-expcomp1.output}}\\n报销列表：{{tool-explist1.output}}","skill":"compliance-check","tools":"sdk__sunshine-biz__list_my_expenses,sdk__sunshine-biz__get_expense_detail,sdk__sunshine-biz__submit_expense","maxIters":"4","systemOverlay":"仅当用户明确要求提交且金额/事由等参数齐全时调用提交报销；否则只输出合规只读结论；禁止虚构金额与单据。","retry.maxAttempts":"1","retry.backoffMs":"500","retry.onFailure":"continue"}},{"id":"answer","type":"answer","displayName":"回答","params":{"prompt":"根据上游检索、工具与 Agent 结论回答用户。\\n\\n约束：禁止向用户暴露英文流程/工具内部名；仅依据下方数据与结论作答，禁止编造。\\n\\n制度：\\n{{rag-expcomp1.output}}\\n\\n报销列表：\\n{{tool-explist1.output}}\\n\\nAgent 结论：\\n{{agent-expcomp1.answer}}","retry.maxAttempts":"2","retry.backoffMs":"500","retry.onFailure":"fail_fast"}}],"edges":[{"from":"start","to":"rag-expcomp1"},{"from":"rag-expcomp1","to":"tool-explist1"},{"from":"tool-explist1","to":"agent-expcomp1"},{"from":"agent-expcomp1","to":"answer"}],"layout":{"start":{"x":48,"y":72},"rag-expcomp1":{"x":248,"y":72},"tool-explist1":{"x":468,"y":72},"agent-expcomp1":{"x":688,"y":72},"answer":{"x":908,"y":72}}}', '{"examples":["网约车上限对照我的报销，必要时帮我提交一笔","对照制度看我的报销是否合规"],"nodeSummary":["start","rag","tool","agent","answer"],"intentAfter":"将按费用合规闭环流程处理"}', CURRENT_TIMESTAMP);

-- oa-task-assist
INSERT INTO workflow_definition (tenant_id, id, display_name, description, mode, enabled, active_version, source, kind) VALUES ('default', 'oa-task-assist', 'OA 待办助手', '列出我的 OA 待办；用户点名 taskId 时可审批（HITL）', 'workflow', 1, 1, 'seed', 'chat');
INSERT INTO workflow_version (tenant_id, workflow_id, version, status, plan_json, catalog_meta, published_at) VALUES ('default', 'oa-task-assist', 1, 'published', '{"planId":null,"reason":"OA 待办助手：list→agent(可 approve)","nodes":[{"id":"start","type":"start","displayName":"开始","params":{}},{"id":"tool-oalist01","type":"tool","displayName":"查询 OA 待办","params":{"tool":"sdk__sunshine-biz__list_oa_tasks","retry.maxAttempts":"2","retry.backoffMs":"500","retry.onFailure":"continue"}},{"id":"agent-oaassist1","type":"agent","displayName":"OA 助手","params":{"query":"{{start.userQuery}}","context":"待办列表：{{tool-oalist01.output}}","tools":"sdk__sunshine-biz__approve_oa_task","maxIters":"3","systemOverlay":"仅审批用户明确点名的 taskId；否则只列示/说明待办；禁止编造 taskId。","retry.maxAttempts":"1","retry.backoffMs":"500","retry.onFailure":"continue"}},{"id":"answer","type":"answer","displayName":"回答","params":{"prompt":"根据上游工具与 Agent 结论回答用户。\\n\\n约束：禁止向用户暴露英文流程/工具内部名；仅依据下方数据与结论作答，禁止编造。\\n\\n待办列表：\\n{{tool-oalist01.output}}\\n\\nAgent 结论：\\n{{agent-oaassist1.answer}}","retry.maxAttempts":"2","retry.backoffMs":"500","retry.onFailure":"fail_fast"}}],"edges":[{"from":"start","to":"tool-oalist01"},{"from":"tool-oalist01","to":"agent-oaassist1"},{"from":"agent-oaassist1","to":"answer"}],"layout":{"start":{"x":48,"y":72},"tool-oalist01":{"x":268,"y":72},"agent-oaassist1":{"x":488,"y":72},"answer":{"x":708,"y":72}}}', '{"examples":["我的 OA 待办有哪些","批准 taskId 为 xxx 的待办"],"nodeSummary":["start","tool","agent","answer"],"intentAfter":"将按 OA 待办助手流程处理"}', CURRENT_TIMESTAMP);

-- expense-detail-query
INSERT INTO workflow_definition (tenant_id, id, display_name, description, mode, enabled, active_version, source, kind) VALUES ('default', 'expense-detail-query', '报销单详情查询', 'parameter-extractor 提取报销单 ID → 查询详情 → 展示（结构化 IO 标杆）', 'workflow', 1, 1, 'seed', 'chat');
INSERT INTO workflow_version (tenant_id, workflow_id, version, status, plan_json, catalog_meta, published_at) VALUES ('default', 'expense-detail-query', 1, 'published', '{"planId":null,"reason":"结构化 IO 标杆：parameter-extractor 提取 expenseId → get_expense_detail 详情","nodes":[{"id":"start","type":"start","displayName":"开始","params":{}},{"id":"pe-extract01","type":"parameter-extractor","displayName":"参数提取","params":{"input":"{{start.userQuery}}","instruction":"从用户问题中提取报销单 ID（expenseId）。如果用户提到多个，取第一个。","schema":"{\\"expenseId\\": {\\"type\\": \\"string\\", \\"description\\": \\"报销单 ID，如 EXP-2024-001\\"}}","retry.maxAttempts":"1","retry.backoffMs":"500","retry.onFailure":"fail_fast"}},{"id":"tool-detail01","type":"tool","displayName":"查询报销详情","params":{"tool":"sdk__sunshine-biz__get_expense_detail","retry.maxAttempts":"2","retry.backoffMs":"500","retry.onFailure":"continue"},"inputs":[{"name":"expenseId","source":"{{pe-extract01.expenseId}}","type":"string","required":true}]},{"id":"answer","type":"answer","displayName":"回答","params":{"prompt":"根据报销单详情回答用户。\\n\\n约束：禁止暴露英文流程/工具内部名；仅依据下方数据作答。\\n\\n报销单详情：\\n{{tool-detail01.output}}","retry.maxAttempts":"2","retry.backoffMs":"500","retry.onFailure":"fail_fast"}}],"edges":[{"from":"start","to":"pe-extract01"},{"from":"pe-extract01","to":"tool-detail01"},{"from":"tool-detail01","to":"answer"}],"layout":{"start":{"x":48,"y":72},"pe-extract01":{"x":248,"y":72},"tool-detail01":{"x":468,"y":72},"answer":{"x":688,"y":72}}}', '{"examples":["查询 EXP-2024-001 的报销详情","帮我看看报销单 EXP-2024-001 的明细"],"nodeSummary":["start","parameter-extractor","tool","answer"],"intentAfter":"将按报销单详情查询流程处理"}', CURRENT_TIMESTAMP);

-- expense-status-filter
INSERT INTO workflow_definition (tenant_id, id, display_name, description, mode, enabled, active_version, source, kind) VALUES ('default', 'expense-status-filter', '报销状态筛选查询', 'variable-assignment 定义查询条件 → 按状态筛选报销单（字面量 inputs 标杆）', 'workflow', 1, 1, 'seed', 'chat');
INSERT INTO workflow_version (tenant_id, workflow_id, version, status, plan_json, catalog_meta, published_at) VALUES ('default', 'expense-status-filter', 1, 'published', '{"planId":null,"reason":"结构化 IO 标杆：variable-assignment 定义 status 变量 → tool 字面量绑定","nodes":[{"id":"start","type":"start","displayName":"开始","params":{}},{"id":"va-setstatus","type":"variable-assignment","displayName":"设置查询条件","params":{"assignments":"[{\\"name\\": \\"targetStatus\\", \\"source\\": \\"pending\\", \\"type\\": \\"string\\"}, {\\"name\\": \\"queryDesc\\", \\"source\\": \\"{{start.userQuery}}\\", \\"type\\": \\"string\\"}]","retry.maxAttempts":"1","retry.backoffMs":"500","retry.onFailure":"fail_fast"}},{"id":"tool-filter01","type":"tool","displayName":"按状态查询报销","params":{"tool":"sdk__sunshine-biz__list_my_expenses","retry.maxAttempts":"2","retry.backoffMs":"500","retry.onFailure":"continue"},"inputs":[{"name":"status","source":"{{va-setstatus.targetStatus}}","type":"string","required":false}]},{"id":"answer","type":"answer","displayName":"回答","params":{"prompt":"根据筛选结果回答用户。\\n\\n约束：禁止暴露英文流程/工具内部名；仅依据下方数据作答。\\n\\n查询条件：{{va-setstatus.targetStatus}}\\n筛选结果：\\n{{tool-filter01.output}}","retry.maxAttempts":"2","retry.backoffMs":"500","retry.onFailure":"fail_fast"}}],"edges":[{"from":"start","to":"va-setstatus"},{"from":"va-setstatus","to":"tool-filter01"},{"from":"tool-filter01","to":"answer"}],"layout":{"start":{"x":48,"y":72},"va-setstatus":{"x":248,"y":72},"tool-filter01":{"x":468,"y":72},"answer":{"x":688,"y":72}}}', '{"examples":["查询我所有待审批的报销单","列出 pending 状态的报销"],"nodeSummary":["start","variable-assignment","tool","answer"],"intentAfter":"将按报销状态筛选查询流程处理"}', CURRENT_TIMESTAMP);

-- expense-amount-check
INSERT INTO workflow_definition (tenant_id, id, display_name, description, mode, enabled, active_version, source, kind) VALUES ('default', 'expense-amount-check', '报销金额合规检查', '查询报销汇总 → 提取总金额 → 合规判断（嵌套路径引用标杆）', 'workflow', 1, 1, 'seed', 'chat');
INSERT INTO workflow_version (tenant_id, workflow_id, version, status, plan_json, catalog_meta, published_at) VALUES ('default', 'expense-amount-check', 1, 'published', '{"planId":null,"reason":"结构化 IO 标杆：tool output 嵌套字段（totalAmount）→ agent 合规分析","nodes":[{"id":"start","type":"start","displayName":"开始","params":{}},{"id":"tool-sumcheck","type":"tool","displayName":"汇总报销金额","params":{"tool":"sdk__sunshine-biz__summarize_my_expenses","retry.maxAttempts":"2","retry.backoffMs":"500","retry.onFailure":"continue"},"inputs":[{"name":"status","source":"approved","type":"string","required":false}]},{"id":"agent-amount01","type":"agent","displayName":"金额合规分析","params":{"query":"{{start.userQuery}}","context":"报销汇总数据：{{tool-sumcheck.output}}\\n已批准报销总金额：{{tool-sumcheck.output.totalAmount}} 元\\n报销单数量：{{tool-sumcheck.output.count}} 笔","skill":"compliance-check","maxIters":"3","systemOverlay":"仅基于上游汇总数据做金额合规分析；禁止编造金额；如总金额超过 10000 元需提示超标风险。","retry.maxAttempts":"1","retry.backoffMs":"500","retry.onFailure":"continue"}},{"id":"answer","type":"answer","displayName":"回答","params":{"prompt":"根据金额合规分析结果回答用户。\\n\\n约束：禁止暴露英文流程/工具内部名；仅依据下方分析作答。\\n\\n合规分析：\\n{{agent-amount01.answer}}","retry.maxAttempts":"2","retry.backoffMs":"500","retry.onFailure":"fail_fast"}}],"edges":[{"from":"start","to":"tool-sumcheck"},{"from":"tool-sumcheck","to":"agent-amount01"},{"from":"agent-amount01","to":"answer"}],"layout":{"start":{"x":48,"y":72},"tool-sumcheck":{"x":268,"y":72},"agent-amount01":{"x":488,"y":72},"answer":{"x":708,"y":72}}}', '{"examples":["我的已批准报销总金额是否超标","检查我的报销金额合规性"],"nodeSummary":["start","tool","agent","answer"],"intentAfter":"将按报销金额合规检查流程处理"}', CURRENT_TIMESTAMP);
